import React, { useState, useEffect } from "react";
import "./Seo_shortform.css";
import { useLocation, useNavigate } from "react-router-dom";

function Seo_shortform({ videoThumbnail }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { message, results, selectedFeatures, selectedClip } = location.state || {};
  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");

  const getVideoUrl = (clipData, fileName) => {
    const baseUrl = "http://127.0.0.1:8000/media/";

    if (clipData?.audio_processing?.enhanced_video_path) {
      const enhancedAudioFileName = clipData.audio_processing.enhanced_video_path.split('\\').pop();
      return `${baseUrl}${enhancedAudioFileName}`;
    }

    if (clipData?.video_upscaling?.processed_file_path) {
      const enhancedVideoFileName = clipData.video_upscaling.processed_file_path.split('\\').pop();
      return `${baseUrl}${enhancedVideoFileName}`;
    }

    return `${baseUrl}${fileName}`;
  };

  // Check if comparison is needed based on selected features
  const shouldShowComparison = (features) => {
    return features?.includes('Noise Reduction') || features?.includes('Video Quality');
  };

  const handleCompare = () => {
  const { results, selectedFeatures, selectedClip } = location.state;

  // Convert the HTTP URL back to local file path format
  const localPath = selectedClip.replace(
    'http://127.0.0.1:8000/media/',
    'C:\\Users\\aqiba\\Desktop\\test3-main\\test3-main\\backend\\media\\'
  );

  // Get the unnested data
  const clipData = Object.values(results)[0] || {};

  // Create result object based on selected features
  let processedResult = {};

  // Prioritize audio processing
  if (selectedFeatures.includes('Noise Reduction') && clipData.audio_processing) {
    processedResult = {
      audio_processing: clipData.audio_processing
    };
  } else if (selectedFeatures.includes('Video Quality') && clipData.video_upscaling) {
    processedResult = {
      video_upscaling: clipData.video_upscaling
    };
  }

  // Navigate with the appropriate data
  navigate('/comparison', {
    state: {
      results: processedResult, // Send only the relevant processing data
      selectedFeatures,
      videoURL: null,
      localVideoPath: localPath,
      seoData: null
    }
  });
};

  useEffect(() => {
    console.log("Received results:", results);
  }, [results]);

  return (
    <div className="seo-app">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
          <button
            className="home-button"
            onClick={() => navigate('/clipper')}
          >
            Home
          </button>
        </nav>
      </header>

      <main className="main-content">
        <button
          className="clipper-btn"
          onClick={() => navigate('/clipper')}
        >
          Go to Clipper
        </button>

        <h3 className="seo-label">SEO Data for Clips</h3>

        <div className="clip-section">
          {Object.entries(results || {}).map(([fileName, clipData], index) => {
            const videoUrl = getVideoUrl(clipData, fileName);
            const seoData = clipData?.seo || {};
            const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
            const description = seoData.description || "No description available.";
            const title = seoData.title || "No title available.";
            const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

            return (
              <div key={index} className="clip-container">
                <div className="clip-content-wrapper">
                  <div className="video-container">
                    <video className="video-player" controls>
                      <source src={videoUrl} type="video/mp4" />
                      Your browser does not support the video tag.
                    </video>
                  </div>

                  <div className="customize-clip">
                    <div className="seo-box">
                      <h2>Title</h2>
                      <p>{title}</p>
                    </div>
                    <div className="seo-box">
                      <h2>Description</h2>
                      <p>{description}</p>
                    </div>
                    <div className="seo-box">
                      <h2>Keywords</h2>
                      <p>{keywords}</p>
                    </div>
                    <div className="seo-box">
                      <h2>Tags</h2>
                      <p>{tags}</p>
                    </div>
                    {shouldShowComparison(selectedFeatures) && (
                      <button
                        className="compare-btn"
                        onClick={() => handleCompare(clipData, fileName)}
                      >
                        Compare Results
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
}

export default Seo_shortform;
